module PluginRegistry
  @plugins = {}
  class << self
    def register(name, impl)
      raise ArgumentError, "duplicate plugin: #{name}" if @plugins.key?(name)
      @plugins[name] = impl
    end
    def lookup(name)
      @plugins.fetch(name) { raise ArgumentError, "unknown plugin: #{name}" }
    end
  end
end
